1→//! Native btrfs delta primitives: generation numbers, `find-new` deltas, and
//! received-subvolume detection.
//!
//! These are the reactive trigger surface for vector replication. An
//! incremental `btrfs send -p <parent> <new> | btrfs receive` lands a
//! subvolume whose *arrival* is the event; `find_new_since` then answers
//! "which files are new" from btrfs's own transaction ids, so nothing has to
//! poll, watch, or diff directory listings.
//!
10→//! `received_uuid` distinguishes a replica (non-empty `Received UUID`) from a
//! locally produced subvolume, so the same binary can tell which side of the
//! send it is running on.

use anyhow::{Context, Result};
use chrono::{DateTime, Utc};
use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use tokio::process::Command;

20→/// Result of a `btrfs subvolume find-new` sweep.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FindNewDelta {
    /// Subvolume-relative paths modified after the requested generation,
    /// deduplicated and sorted (one file can report many extents).
    pub files: Vec<PathBuf>,
    /// The `transid marker was N` trailer: the generation to pass as
    /// `lastgen` on the next sweep.
    pub transid: u64,
}
30→
/// Files changed in `subvolume` *strictly after* generation `already_indexed`.
///
/// Pass `0` for a full sweep. The returned `transid` is the checkpoint for the
/// next call — persist it, not a wall-clock timestamp.
pub async fn find_new_since(subvolume: &Path, already_indexed: u64) -> Result<FindNewDelta> {
    let min_transid = min_transid_arg(already_indexed);
    let output = Command::new("btrfs")
        .args(["subvolume", "find-new"])
        .arg(subvolume)
40→        .arg(min_transid.to_string())
        .output()
        .await
        .context("failed to execute `btrfs subvolume find-new`")?;

    if !output.status.success() {
        anyhow::bail!(
            "`btrfs subvolume find-new {} {}` failed: {}",
            subvolume.display(),
            min_transid,
50→            String::from_utf8_lossy(&output.stderr).trim()
        );
    }

    Ok(parse_find_new(&String::from_utf8_lossy(&output.stdout)))
}

/// `find-new`'s generation argument is the *minimum* transid it reports, i.e.
/// inclusive: asking for the marker it just returned re-reports the same files.
/// Callers hold "already indexed through N", so the query starts at N+1.
60→fn min_transid_arg(already_indexed: u64) -> u64 {
    already_indexed.saturating_add(1)
}

/// Current generation of a subvolume, from `btrfs subvolume show`.
pub async fn generation(subvolume: &Path) -> Result<u64> {
    let show = subvolume_show(subvolume).await?;
    parse_generation(&show).with_context(|| {
        format!(
            "no Generation field in `btrfs subvolume show {}`",
70→            subvolume.display()
        )
    })
}

/// When a subvolume (or snapshot) was created, per btrfs's own metadata.
///
/// The filesystem inode's birth/mtime cannot answer this for a snapshot: those
/// are inherited from the source subvolume, so every snapshot of one subvolume
/// looks equally old. Only `btrfs subvolume show` knows the snapshot's own
80→/// creation time, which is what any retention policy has to bucket on.
pub async fn creation_time(subvolume: &Path) -> Result<Option<DateTime<Utc>>> {
    let show = subvolume_show(subvolume).await?;
    Ok(parse_creation_time(&show))
}

/// `Received UUID` of a subvolume, or `None` when it was produced locally.
///
/// A non-`None` value means this subvolume arrived through `btrfs receive`,
/// i.e. this host is the replication target rather than the origin.
90→pub async fn received_uuid(subvolume: &Path) -> Result<Option<String>> {
    let show = subvolume_show(subvolume).await?;
    Ok(parse_received_uuid(&show))
}

async fn subvolume_show(subvolume: &Path) -> Result<String> {
    let output = Command::new("btrfs")
        .args(["subvolume", "show"])
        .arg(subvolume)
        .output()
100→        .await
        .context("failed to execute `btrfs subvolume show`")?;

    if !output.status.success() {
        anyhow::bail!(
            "`btrfs subvolume show {}` failed: {}",
            subvolume.display(),
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
110→
    Ok(String::from_utf8_lossy(&output.stdout).into_owned())
}

/// Parse `find-new` output. Each extent line ends with the subvolume-relative
/// path after the `flags <FLAGS>` field; splitting there (rather than taking
/// the last whitespace token) keeps paths containing spaces intact.
fn parse_find_new(stdout: &str) -> FindNewDelta {
    let mut files = BTreeSet::new();
    let mut transid = 0u64;
120→
    for line in stdout.lines() {
        let line = line.trim_end();
        if let Some(rest) = line.strip_prefix("transid marker was ") {
            transid = rest.trim().parse().unwrap_or(transid);
            continue;
        }
        if !line.starts_with("inode ") {
            continue;
        }
130→        // `... gen 110097 flags NONE some/path.bin`
        let Some((_, after_flags)) = line.split_once(" flags ") else {
            continue;
        };
        let Some((_flags, path)) = after_flags.split_once(' ') else {
            continue;
        };
        if !path.is_empty() {
            files.insert(PathBuf::from(path));
        }
140→    }

    FindNewDelta {
        files: files.into_iter().collect(),
        transid,
    }
}

fn parse_generation(show: &str) -> Option<u64> {
    show.lines()
150→        .filter_map(|line| line.trim().strip_prefix("Generation:"))
        .find_map(|value| value.trim().parse().ok())
}

/// Parse `Creation time: 2026-08-08 07:11:42 +0000`.
fn parse_creation_time(show: &str) -> Option<DateTime<Utc>> {
    show.lines()
        .filter_map(|line| line.trim().strip_prefix("Creation time:"))
        .find_map(|value| {
            DateTime::parse_from_str(value.trim(), "%Y-%m-%d %H:%M:%S %z")
160→                .ok()
                .map(|dt| dt.with_timezone(&Utc))
        })
}

fn parse_received_uuid(show: &str) -> Option<String> {
    show.lines()
        .filter_map(|line| line.trim().strip_prefix("Received UUID:"))
        .map(str::trim)
        .find(|value| !value.is_empty() && *value != "-")
170→        .map(str::to_string)
}

#[cfg(test)]
mod tests {
    use super::*;

    const FIND_NEW: &str = "\
inode 257 file offset 0 len 4096 disk start 13631488 offset 0 gen 110097 flags NONE vec-000000000001.bin
inode 257 file offset 4096 len 4096 disk start 13635584 offset 0 gen 110097 flags NONE vec-000000000001.bin
180→inode 258 file offset 0 len 12 disk start 0 offset 0 gen 110098 flags INLINE vec-000000000002.bin
transid marker was 110099
";

    #[test]
    fn parses_find_new_deduped_and_sorted() {
        let delta = parse_find_new(FIND_NEW);
        assert_eq!(
            delta.files,
            vec![
190→                PathBuf::from("vec-000000000001.bin"),
                PathBuf::from("vec-000000000002.bin"),
            ],
            "multiple extents of one file must collapse to a single entry"
        );
        assert_eq!(delta.transid, 110099);
    }

    #[test]
    fn parses_find_new_with_no_changes() {
200→        let delta = parse_find_new("transid marker was 110096\n");
        assert!(delta.files.is_empty());
        assert_eq!(delta.transid, 110096);
    }

    #[test]
    fn query_starts_one_past_the_indexed_generation() {
        // Verified against btrfs-progs on the live chain: `find-new <sv> 111728`
        // still lists the files whose gen is exactly 111728.
        assert_eq!(min_transid_arg(111728), 111729);
210→        assert_eq!(min_transid_arg(0), 1, "a full sweep still starts at gen 1");
        assert_eq!(min_transid_arg(u64::MAX), u64::MAX, "must not wrap");
    }

    #[test]
    fn keeps_paths_containing_spaces() {
        let delta = parse_find_new(
            "inode 257 file offset 0 len 4096 disk start 0 offset 0 gen 5 flags NONE dir with space/v.bin\ntransid marker was 6\n",
        );
        assert_eq!(delta.files, vec![PathBuf::from("dir with space/v.bin")]);
220→    }

    #[test]
    fn parses_generation_and_received_uuid() {
        let show = "\
@/var/lib/opdbus/snowball/vectors
\tName: \t\t\tvectors
\tUUID: \t\t\t28ae1fdf-1601-eb4b-9345-fe76ea28e348
\tParent UUID: \t\t-
\tReceived UUID: \t\t-
230→\tCreation time: \t\t2026-08-08 07:11:42 +0000
\tGeneration: \t\t110096
";
        assert_eq!(parse_generation(show), Some(110096));
        assert_eq!(
            parse_creation_time(show).map(|dt| dt.to_rfc3339()),
            Some("2026-08-08T07:11:42+00:00".to_string()),
            "retention must bucket on the snapshot's own creation time"
        );
        assert_eq!(
240→            parse_creation_time("\tCreation time: \t\t2026-08-08 02:11:42 -0500")
                .map(|dt| dt.to_rfc3339()),
            Some("2026-08-08T07:11:42+00:00".to_string()),
            "non-UTC offsets must normalize"
        );
        assert_eq!(parse_creation_time("no such field"), None);
        assert_eq!(
            parse_received_uuid(show),
            None,
            "a locally produced subvolume reports '-'"
250→        );

        let replica = show.replace(
            "Received UUID: \t\t-",
            "Received UUID: \t\t9c1b7e64-1111-2222-3333-444455556666",
        );
        assert_eq!(
            parse_received_uuid(&replica).as_deref(),
            Some("9c1b7e64-1111-2222-3333-444455556666")
        );
260→    }
}

1→//! Block events and plugin footprints for the streaming snowball

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use simd_json::prelude::*;
use std::collections::HashMap;

/// A block event in the streaming snowball
#[derive(Debug, Clone, Serialize, Deserialize)]
10→pub struct BlockEvent {
    pub timestamp: u64,
    pub category: String,
    pub action: String,
    pub data: simd_json::OwnedValue,
    pub hash: String,
    pub vector: Vec<f32>,
}

impl BlockEvent {
20→    /// Create a new block event
    pub fn new(
        category: impl Into<String>,
        action: impl Into<String>,
        data: simd_json::OwnedValue,
    ) -> Self {
        let timestamp = chrono::Utc::now().timestamp_millis() as u64;
        let category = category.into();
        let action = action.into();

30→        // Compute hash
        let hash_input = format!("{}:{}:{}:{}", timestamp, category, action, data);
        let mut hasher = Sha256::new();
        hasher.update(hash_input.as_bytes());
        let hash = format!("{:x}", hasher.finalize());

        Self {
            timestamp,
            category,
            action,
40→            data,
            hash,
            vector: Vec::new(), // Empty vector, can be populated by ML
        }
    }

    /// Create with a pre-computed vector
    pub fn with_vector(mut self, vector: Vec<f32>) -> Self {
        self.vector = vector;
        self
50→    }
}

/// A payload envelope carried from a plugin/sled into the timing and vector
/// projections. A footprint is deliberately not a digest: Snowball consumes
/// the payload directly, while the authoritative chain owns hashing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PluginFootprint {
    pub plugin_id: String,
    pub operation: String,
60→    pub timestamp: u64,
    pub payload: simd_json::OwnedValue,
    pub metadata: HashMap<String, simd_json::OwnedValue>,
    pub vector_features: Vec<f32>,
}

impl PluginFootprint {
    /// Create a new plugin footprint
    pub fn new(
        plugin_id: impl Into<String>,
70→        operation: impl Into<String>,
        data: &simd_json::OwnedValue,
    ) -> Self {
        let timestamp = chrono::Utc::now().timestamp_millis() as u64;

        Self {
            plugin_id: plugin_id.into(),
            operation: operation.into(),
            timestamp,
            payload: data.clone(),
80→            metadata: HashMap::new(),
            vector_features: Vec::new(),
        }
    }

    /// Add metadata
    pub fn with_metadata(mut self, key: impl Into<String>, value: simd_json::OwnedValue) -> Self {
        self.metadata.insert(key.into(), value);
        self
    }
90→
    /// Convert to a BlockEvent.
    ///
    /// Timing is written first and the vector is left empty. Live vectorization
    /// fills it later. This is the pre-snowball rule from
    /// `operation-dbus-proto` `crates/op-blockchain/src/blockchain.rs`
    /// (`add_event`: timing is authoritative, vectors are async projections)
    /// and `footprint.rs` (`to_block_event` drops the vector). A snapshot can
    /// therefore name a block whose vector file was still being written.
    pub fn to_block_event(&self) -> BlockEvent {
100→        let data = simd_json::json!({
            "plugin_id": self.plugin_id,
            "operation": self.operation,
            "payload": self.payload,
            "metadata": self.metadata
        });

        // A persisted ChainEvent already owns the Snowball chain hash. Reuse
        // it directly; never hash that hash through an intermediate footprint.
        if let Some(chain_hash) = self
110→            .payload
            .get("event_hash")
            .and_then(simd_json::prelude::ValueAsScalar::as_str)
        {
            return BlockEvent {
                timestamp: self.timestamp,
                category: self.plugin_id.clone(),
                action: self.operation.clone(),
                data,
                hash: chain_hash.to_string(),
120→                vector: Vec::new(),
            };
        }
        BlockEvent::new(self.plugin_id.clone(), self.operation.clone(), data)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
130→
    #[test]
    fn test_block_event_creation() {
        let event = BlockEvent::new("test", "create", simd_json::json!({"key": "value"}));

        assert!(!event.hash.is_empty());
        assert_eq!(event.category, "test");
        assert_eq!(event.action, "create");
    }

140→    #[test]
    fn test_plugin_footprint_creation() {
        let footprint = PluginFootprint::new(
            "systemd",
            "unit_started",
            &simd_json::json!({"unit": "nginx.service"}),
        );

        assert_eq!(footprint.plugin_id, "systemd");
        assert_eq!(footprint.payload["unit"], "nginx.service");
150→    }

    #[test]
    fn chain_event_hash_is_carried_without_hashing_the_hash() {
        let expected = "ab".repeat(32);
        let footprint = PluginFootprint::new(
            "identity_sled",
            "session_arrival",
            &simd_json::json!({
                "event_hash": expected.clone(),
160→                "input_payload": {"session_id": "session-a"}
            }),
        );
        let event = footprint.to_block_event();
        assert_eq!(event.hash, expected);
        assert_eq!(
            event.data["payload"]["input_payload"]["session_id"],
            "session-a"
        );
    }
170→}

1→//! Snapshot interval configuration

use serde::{Deserialize, Serialize};
use std::time::Duration;
use tracing::warn;

/// Snapshot interval options
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum SnapshotInterval {
10→    /// Snapshot after every operation
    PerOperation,
    /// Snapshot every minute
    EveryMinute,
    /// Snapshot every 5 minutes
    Every5Minutes,
    /// Snapshot every 15 minutes
    #[default]
    Every15Minutes,
    /// Snapshot every 30 minutes
20→    Every30Minutes,
    /// Snapshot every hour
    Hourly,
    /// Snapshot every day
    Daily,
    /// Snapshot every week
    Weekly,
    /// Snapshots are requested explicitly by the storage owner, never by appends.
    Manual,
}
30→
impl SnapshotInterval {
    /// Parse from environment variable
    pub fn from_env() -> Self {
        match std::env::var("OPDBUS_SNAPSHOT_INTERVAL")
            .unwrap_or_else(|_| "every-15-minutes".to_string())
            .to_lowercase()
            .as_str()
        {
            "per-op" | "per-operation" | "per_operation" => SnapshotInterval::PerOperation,
40→            "every-minute" | "1-minute" | "1min" => SnapshotInterval::EveryMinute,
            "every-5-minutes" | "5-minutes" | "5min" => SnapshotInterval::Every5Minutes,
            "every-15-minutes" | "15-minutes" | "15min" => SnapshotInterval::Every15Minutes,
            "every-30-minutes" | "30-minutes" | "30min" => SnapshotInterval::Every30Minutes,
            "hourly" | "1-hour" | "1h" => SnapshotInterval::Hourly,
            "daily" | "1-day" | "1d" => SnapshotInterval::Daily,
            "weekly" | "1-week" | "1w" => SnapshotInterval::Weekly,
            "manual" => SnapshotInterval::Manual,
            _ => {
                warn!("Invalid OPDBUS_SNAPSHOT_INTERVAL, defaulting to every-15-minutes");
50→                SnapshotInterval::Every15Minutes
            }
        }
    }

    /// Parse from string
    pub fn parse(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "per-op" | "per-operation" | "per_operation" => Some(SnapshotInterval::PerOperation),
            "every-minute" | "1-minute" | "1min" | "minute" => Some(SnapshotInterval::EveryMinute),
60→            "every-5-minutes" | "5-minutes" | "5min" => Some(SnapshotInterval::Every5Minutes),
            "every-15-minutes" | "15-minutes" | "15min" => Some(SnapshotInterval::Every15Minutes),
            "every-30-minutes" | "30-minutes" | "30min" => Some(SnapshotInterval::Every30Minutes),
            "hourly" | "1-hour" | "1h" | "hour" => Some(SnapshotInterval::Hourly),
            "daily" | "1-day" | "1d" | "day" => Some(SnapshotInterval::Daily),
            "weekly" | "1-week" | "1w" | "week" => Some(SnapshotInterval::Weekly),
            "manual" => Some(SnapshotInterval::Manual),
            _ => None,
        }
    }
70→
    /// Get the duration for this interval
    /// Returns None for PerOperation and Manual, which have no timed schedule.
    pub fn as_duration(&self) -> Option<Duration> {
        match self {
            SnapshotInterval::PerOperation | SnapshotInterval::Manual => None,
            SnapshotInterval::EveryMinute => Some(Duration::from_secs(60)),
            SnapshotInterval::Every5Minutes => Some(Duration::from_secs(5 * 60)),
            SnapshotInterval::Every15Minutes => Some(Duration::from_secs(15 * 60)),
            SnapshotInterval::Every30Minutes => Some(Duration::from_secs(30 * 60)),
80→            SnapshotInterval::Hourly => Some(Duration::from_secs(60 * 60)),
            SnapshotInterval::Daily => Some(Duration::from_secs(24 * 60 * 60)),
            SnapshotInterval::Weekly => Some(Duration::from_secs(7 * 24 * 60 * 60)),
        }
    }

    /// Check if enough time has passed since the last snapshot
    pub fn should_snapshot(&self, elapsed: Duration) -> bool {
        if matches!(self, SnapshotInterval::Manual) {
            return false;
90→        }
        match self.as_duration() {
            None => true, // PerOperation always snapshots
            Some(interval) => elapsed >= interval,
        }
    }

    /// Human-readable description
    pub fn description(&self) -> &'static str {
        match self {
100→            SnapshotInterval::PerOperation => "after every operation",
            SnapshotInterval::EveryMinute => "every minute",
            SnapshotInterval::Every5Minutes => "every 5 minutes",
            SnapshotInterval::Every15Minutes => "every 15 minutes",
            SnapshotInterval::Every30Minutes => "every 30 minutes",
            SnapshotInterval::Hourly => "every hour",
            SnapshotInterval::Daily => "every day",
            SnapshotInterval::Weekly => "every week",
            SnapshotInterval::Manual => "explicit storage-owner requests only",
        }
110→    }
}

impl std::fmt::Display for SnapshotInterval {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.description())
    }
}

#[cfg(test)]
120→mod tests {
    use super::*;

    #[test]
    fn manual_interval_never_schedules_snapshots() {
        for elapsed in [Duration::ZERO, Duration::from_secs(15 * 60), Duration::MAX] {
            assert!(!SnapshotInterval::Manual.should_snapshot(elapsed));
            assert!(SnapshotInterval::PerOperation.should_snapshot(elapsed));
        }
        assert!(!SnapshotInterval::Every15Minutes.should_snapshot(Duration::from_secs(899)));
130→        assert!(SnapshotInterval::Every15Minutes.should_snapshot(Duration::from_secs(900)));
    }

    #[test]
    fn test_duration() {
        assert!(SnapshotInterval::PerOperation.as_duration().is_none());
        assert_eq!(
            SnapshotInterval::EveryMinute.as_duration(),
            Some(Duration::from_secs(60))
        );
140→        assert_eq!(
            SnapshotInterval::Hourly.as_duration(),
            Some(Duration::from_secs(3600))
        );
    }

    #[test]
    fn test_from_str() {
        assert_eq!(
            SnapshotInterval::parse("hourly"),
150→            Some(SnapshotInterval::Hourly)
        );
        assert_eq!(
            SnapshotInterval::parse("15min"),
            Some(SnapshotInterval::Every15Minutes)
        );
        assert_eq!(SnapshotInterval::parse("invalid"), None);
    }
}

1→//! Stored snapshot-retention fields.
//!
//! Prune keeps the newest committed dump, the parent of the next send. That
//! dump is a snapshot of the live vectors. Timing in the same dump accounts
//! for a vector that was still being written. The hourly, daily, weekly, and
//! quarterly counts remain so an existing `retention.json` and the snowball
//! method still load. They do not keep extra dumps.

use anyhow::Result;
10→use serde::{Deserialize, Serialize};
use simd_json::prelude::*;

/// Snapshot retention policy with rolling windows
#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
pub struct RetentionPolicy {
    /// Keep last N hourly snapshots
    pub hourly: usize,
    /// Keep last N daily snapshots
    pub daily: usize,
20→    /// Keep last N weekly snapshots
    pub weekly: usize,
    /// Keep last N quarterly snapshots
    pub quarterly: usize,
}

impl Default for RetentionPolicy {
    fn default() -> Self {
        Self {
            hourly: 5,
30→            daily: 5,
            weekly: 5,
            quarterly: 5,
        }
    }
}

impl RetentionPolicy {
    /// Create a new retention policy with explicit values
    pub fn new(hourly: usize, daily: usize, weekly: usize, quarterly: usize) -> Self {
40→        Self {
            hourly,
            daily,
            weekly,
            quarterly,
        }
    }

    /// Create a minimal retention policy (for testing)
    pub fn minimal() -> Self {
50→        Self {
            hourly: 2,
            daily: 2,
            weekly: 2,
            quarterly: 2,
        }
    }

    /// Create a comprehensive retention policy (for production)
    pub fn comprehensive() -> Self {
60→        Self {
