        kept.extend_from_slice(&buffer[..retain]);
270→        truncated |= retain < count;
    }
    let mut text = String::from_utf8_lossy(&kept).into_owned();
    if truncated {
        text.push_str("\n[diagnostics truncated]");
    }
    Ok(text)
}

